"use client";

import React, { useEffect, useState } from "react";
import { Activity, Zap, ShieldCheck, Radio, ArrowUpRight, ArrowDownRight } from "lucide-react";
import { Card, CardContent } from "@/components/ui/card";
import { NodeBasicInfo } from "@/contexts/NodeListContext";
import { LiveData } from "@/types/LiveData";
import { formatBytes } from "@/utils/unitHelper";
const formatSpeed = (bytes: number) => `${formatBytes(bytes)}/s`;

interface NasdaqMarketBoardProps {
  nodes: NodeBasicInfo[];
  liveData: LiveData;
}

interface MarketIndex {
  code: string;
  name: string;
  price: number;
  change: number;
  changePercent: number;
  sparkline: number[];
  unit?: string;
}

export const NasdaqMarketBoard: React.FC<NasdaqMarketBoardProps> = ({ nodes, liveData }) => {
  const [indices, setIndices] = useState<MarketIndex[]>([
    {
      code: ".IXIC",
      name: "纳斯达克综合指数",
      price: 18245.81,
      change: 207.35,
      changePercent: 1.15,
      sparkline: [18100, 18120, 18110, 18150, 18190, 18170, 18210, 18230, 18245],
    },
    {
      code: ".INX",
      name: "标普 500 指数",
      price: 5751.13,
      change: 43.82,
      changePercent: 0.77,
      sparkline: [5720, 5725, 5730, 5728, 5740, 5735, 5745, 5748, 5751],
    },
    {
      code: "TECH7",
      name: "科技巨头领涨指数",
      price: 2488.60,
      change: 53.10,
      changePercent: 2.18,
      sparkline: [2430, 2445, 2440, 2460, 2470, 2465, 2478, 2482, 2488],
    },
    {
      code: "BTC",
      name: "加密流动性基准",
      price: 63820.00,
      change: 1768.50,
      changePercent: 2.85,
      unit: "$",
      sparkline: [62200, 62500, 62400, 62800, 63100, 63000, 63400, 63600, 63820],
    },
  ]);

  useEffect(() => {
    const timer = setInterval(() => {
      setIndices((prev) =>
        prev.map((item) => {
          const delta = (Math.random() - 0.47) * (item.price * 0.001);
          const newPrice = Math.round((item.price + delta) * 100) / 100;
          const newChange = Math.round((item.change + delta) * 100) / 100;
          const newPercent = Math.round((newChange / (newPrice - newChange)) * 10000) / 100;
          const newSparkline = [...item.sparkline.slice(1), newPrice];
          return {
            ...item,
            price: newPrice,
            change: newChange,
            changePercent: newPercent,
            sparkline: newSparkline,
          };
        })
      );
    }, 3000);
    return () => clearInterval(timer);
  }, []);

  const totalNodes = nodes?.length || 0;
  const onlineCount = liveData?.online?.length || 0;
  const offlineCount = Math.max(0, totalNodes - onlineCount);
  const onlineRatio = totalNodes > 0 ? Math.round((onlineCount / totalNodes) * 100) : 100;

  const onlineSet = new Set(liveData?.online || []);
  const activeNodeData = Object.entries(liveData?.data || {})
    .filter(([uuid]) => onlineSet.has(uuid))
    .map(([, data]) => data);

  const totalUpTraffic = activeNodeData.reduce((acc, n) => acc + (n.network.totalUp || 0), 0);
  const totalDownTraffic = activeNodeData.reduce((acc, n) => acc + (n.network.totalDown || 0), 0);
  const currentUpSpeed = activeNodeData.reduce((acc, n) => acc + (n.network.up || 0), 0);
  const currentDownSpeed = activeNodeData.reduce((acc, n) => acc + (n.network.down || 0), 0);

  return (
    <div className="w-full space-y-4">
      {/* 纳斯达克交易大屏 顶部标头 */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-2 p-3 bg-gradient-to-r from-[#04070e] via-[#080d1a] to-[#04070e] border border-[#00f293]/25 rounded-lg shadow-lg">
        <div className="flex items-center gap-3">
          <div className="flex items-center justify-center w-8 h-8 rounded bg-[#00f293]/15 border border-[#00f293]/40 text-[#00f293] shadow-[0_0_10px_rgba(0,242,147,0.3)]">
            <Radio className="w-4 h-4 animate-pulse" />
          </div>
          <div>
            <div className="flex items-center gap-2">
              <span className="font-bold text-sm tracking-wider text-[#e6edf3] font-mono">NASDAQ // 纳斯达克金融监控大屏</span>
              <span className="px-1.5 py-0.5 rounded text-[10px] font-bold bg-[#00f293]/20 text-[#00f293] border border-[#00f293]/40">
                实时撮合中
              </span>
            </div>
            <p className="text-[11px] text-[#8b949e] font-mono">
              美东市场状态：连续竞价 (MARKET OPEN) | 专线直连延迟：24ms
            </p>
          </div>
        </div>

        <div className="flex items-center gap-4 text-xs font-mono">
          <div className="flex items-center gap-1.5 text-[#00f293]">
            <span className="w-2 h-2 rounded-full bg-[#00f293] shadow-[0_0_6px_#00f293] animate-ping" />
            <span>标的健康度: 100.0% 优</span>
          </div>
          <div className="hidden md:flex items-center gap-1 text-[#8b949e]">
            <span>撮合引擎: v2.5.0-HFT</span>
          </div>
        </div>
      </div>

      {/* 核心大盘指数 4 宫格 */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3">
        {indices.map((idx) => {
          const isUp = idx.change >= 0;
          return (
            <Card
              key={idx.code}
              className="relative overflow-hidden bg-[#080d18]/90 border border-[#00f293]/20 hover:border-[#00f293]/50 transition-all duration-200 shadow-md group"
            >
              <div className="absolute top-0 left-0 w-2 h-0.5 bg-[#00f293]" />
              <CardContent className="p-3.5 space-y-2">
                <div className="flex items-center justify-between text-xs font-mono">
                  <span className="text-[#8b949e] font-medium">{idx.name}</span>
                  <span className="text-[10px] px-1.5 py-0.5 rounded bg-white/5 text-[#7d8b99]">{idx.code}</span>
                </div>

                <div className="flex items-baseline justify-between">
                  <div className="text-xl sm:text-2xl font-bold font-mono tracking-tight text-[#f0f6fc]">
                    {idx.unit ? idx.unit : ""}{idx.price.toLocaleString("en-US", { minimumFractionDigits: 2 })}
                  </div>
                  <div
                    className={`flex items-center gap-0.5 text-xs font-bold font-mono ${
                      isUp ? "text-[#00f293] drop-shadow-[0_0_8px_rgba(0,242,147,0.4)]" : "text-[#ff334b] drop-shadow-[0_0_8px_rgba(255,51,75,0.4)]"
                    }`}
                  >
                    {isUp ? <ArrowUpRight className="w-3.5 h-3.5" /> : <ArrowDownRight className="w-3.5 h-3.5" />}
                    <span>{isUp ? "+" : ""}{idx.changePercent.toFixed(2)}%</span>
                  </div>
                </div>

                {/* 迷你 Sparkline 走势图 */}
                <div className="h-6 w-full pt-1">
                  <svg className="w-full h-full overflow-visible" preserveAspectRatio="none" viewBox="0 0 100 24">
                    <polyline
                      fill="none"
                      stroke={isUp ? "#00f293" : "#ff334b"}
                      strokeWidth="1.8"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      points={idx.sparkline
                        .map((val, i) => {
                          const min = Math.min(...idx.sparkline);
                          const max = Math.max(...idx.sparkline);
                          const range = max - min || 1;
                          const y = 20 - ((val - min) / range) * 16;
                          const x = (i / (idx.sparkline.length - 1)) * 100;
                          return `${x},${y}`;
                        })
                        .join(" ")}
                    />
                  </svg>
                </div>
              </CardContent>
            </Card>
          );
        })}
      </div>

      {/* 市场遥测大屏看板：多空分布与全网撮合流动性 */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-3">
        {/* 多空分布看板 */}
        <Card className="bg-[#080d18]/90 border border-[#00f293]/20 shadow-md p-4 space-y-3">
          <div className="flex items-center justify-between border-b border-white/5 pb-2">
            <span className="text-xs font-bold font-mono text-[#e6edf3] flex items-center gap-1.5">
              <Activity className="w-4 h-4 text-[#00f293]" />
              标的多空强弱矩阵 (BULL / BEAR)
            </span>
            <span className="text-[10px] text-[#00f293] font-mono">100% 极强</span>
          </div>

          <div className="space-y-2">
            <div className="flex justify-between text-xs font-mono">
              <span className="text-[#8b949e]">做多 · 正常在线</span>
              <span className="text-[#00f293] font-bold">{onlineCount} 支 ({onlineRatio}%)</span>
            </div>
            <div className="w-full h-2 rounded bg-white/5 overflow-hidden">
              <div
                className="h-full bg-[#00f293] shadow-[0_0_8px_#00f293] transition-all duration-500"
                style={{ width: `${onlineRatio}%` }}
              />
            </div>
            <div className="flex justify-between text-[11px] font-mono text-[#8b949e]">
              <span>做空 · 停牌离线: <strong className="text-[#ff334b]">{offlineCount}</strong> 支</span>
              <span>挂牌总数: <strong className="text-[#f0f6fc]">{totalNodes}</strong> 支</span>
            </div>
          </div>
        </Card>

        {/* 成交流量看板 */}
        <Card className="bg-[#080d18]/90 border border-[#00f293]/20 shadow-md p-4 space-y-3">
          <div className="flex items-center justify-between border-b border-white/5 pb-2">
            <span className="text-xs font-bold font-mono text-[#e6edf3] flex items-center gap-1.5">
              <Zap className="w-4 h-4 text-[#00b4d8]" />
              全网累计成交流量 (LIQUIDITY POOL)
            </span>
            <span className="text-[10px] text-[#00b4d8] font-mono">双向对冲</span>
          </div>

          <div className="grid grid-cols-2 gap-2 text-xs font-mono">
            <div className="p-2 rounded bg-white/5 border border-white/5">
              <div className="text-[10px] text-[#8b949e]">多头流入 (IN)</div>
              <div className="text-sm font-bold text-[#00f293] mt-0.5">{formatBytes(totalUpTraffic)}</div>
            </div>
            <div className="p-2 rounded bg-white/5 border border-white/5">
              <div className="text-[10px] text-[#8b949e]">空头流出 (OUT)</div>
              <div className="text-sm font-bold text-[#00b4d8] mt-0.5">{formatBytes(totalDownTraffic)}</div>
            </div>
          </div>
        </Card>

        {/* 撮合吞吐看板 */}
        <Card className="bg-[#080d18]/90 border border-[#00f293]/20 shadow-md p-4 space-y-3">
          <div className="flex items-center justify-between border-b border-white/5 pb-2">
            <span className="text-xs font-bold font-mono text-[#e6edf3] flex items-center gap-1.5">
              <ShieldCheck className="w-4 h-4 text-[#ffb703]" />
              实时撮合吞吐速率 (HFT SPEED)
            </span>
            <span className="text-[10px] text-[#ffb703] font-mono">极速通道</span>
          </div>

          <div className="grid grid-cols-2 gap-2 text-xs font-mono">
            <div className="p-2 rounded bg-white/5 border border-white/5">
              <div className="text-[10px] text-[#8b949e]">上行撮合速率</div>
              <div className="text-sm font-bold text-[#00f293] mt-0.5">{formatSpeed(currentUpSpeed)}</div>
            </div>
            <div className="p-2 rounded bg-white/5 border border-white/5">
              <div className="text-[10px] text-[#8b949e]">下行接收速率</div>
              <div className="text-sm font-bold text-[#00b4d8] mt-0.5">{formatSpeed(currentDownSpeed)}</div>
            </div>
          </div>
        </Card>
      </div>
    </div>
  );
};
